    lateinit var request: HttpRequestData
    val repository = repository { incoming ->
        request = incoming
        respond(
            content = """
                {"base":"USD","start_date":"2026-10-12","end_date":"2026-11-10","rates":{
                    "2026-11-10":{"EUR":0.89},
                    "2026-10-13":{"EUR":0.88}
                }}
            """.trimIndent(),
            headers = jsonHeaders,
        )
    }

    val history = repository.getRateHistory(base = "USD", code = "EUR")

    request.url.encodedPath shouldEndWith "2026-10-13.."
    request.url.parameters["base"] shouldBe "USD"

/**
 * The rates of [code] against [base] for the last 30 calendar days, today included, oldest first. Empty when
 * there is no data for that window.
 */
suspend fun getRateHistory(base: String, code: String): List<RatePoint>

